import{_ as t,o as d,c as a,a2 as r}from"./chunks/framework.BbQUUm7J.js";const u=JSON.parse('{"title":"Environment Variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1794936786000}'),o={name:"reference/environment.md"};function i(s,e,n,c,l,h){return d(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h1><p>The exhaustive reference. Audited 2026-11-17 by grepping every environment access across <code>src/</code>, <code>lib/</code>, <code>bin/</code> and <code>scripts/</code>, then cross-checked against <code>.env.example</code> — if a variable is listed here, the source reads it; the config-file equivalent (<code>config.toml</code> network profiles) is covered in <a href="/furlpay-cli/guide/configuration">Configuration &amp; Diagnostics</a>.</p><p>Secrets live in environment variables or stdin — <strong>never as CLI arguments</strong> (argv is visible in process listings and shell history). Variables without the <code>NEXT_PUBLIC_</code> style prefix never reach any client bundle; they are read only by the local process.</p><h2 id="setup-precedence" tabindex="-1">Setup &amp; precedence <a class="header-anchor" href="#setup-precedence" aria-label="Permalink to &quot;Setup &amp; precedence&quot;">​</a></h2><p>Bash / macOS / Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HYPERLIQUID_PRIVATE_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0x...&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or an env file you source</span></span></code></pre></div><p>Windows PowerShell (current session):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HYPERLIQUID_PRIVATE_KEY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0x...&quot;</span></span></code></pre></div><p>Persisted per-user: <code>setx NAME value</code> (new shells only) or a <code>$PROFILE</code> script. Never place secrets in cloud-synced directories.</p><p>Precedence: <strong>real environment &gt; <code>.env</code> file</strong> (loaded by dotenv from the working directory) <strong>&gt; built-in default</strong>. A value set in the shell wins over <code>.env</code>.</p><p>Rotation: API keys are read at process start — rotating a key takes effect on the next invocation. The keystore master key rotates by re-importing (<code>wallet import</code>). Redaction is property-tested: private keys never appear in errors, <code>toString</code>, JSON, or signature envelopes (<code>test/key-redaction.test.js</code>).</p><h2 id="signing-keys" tabindex="-1">Signing keys <a class="header-anchor" href="#signing-keys" aria-label="Permalink to &quot;Signing keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Used by</th><th>Notes</th></tr></thead><tbody><tr><td><code>HYPERLIQUID_PRIVATE_KEY</code></td><td>Perp execution, HLP vault</td><td>Preferred. Fails closed if absent on signed surfaces. Use a delegated <strong>API Agent key</strong>, not your master</td></tr><tr><td><code>ETH_PRIVATE_KEY</code></td><td>Perp execution, HLP vault</td><td>Fallback signer (same code path)</td></tr><tr><td><code>FURLPAY_HL_TESTNET</code></td><td>Hyperliquid</td><td><code>1</code> = testnet, <code>0</code> = mainnet — explicit, never silently swapped</td></tr><tr><td><code>HYPERLIQUID_WALLET_ADDRESS</code></td><td>Read-only account views</td><td>Default address for <code>account balance/positions/orders</code>; a signer is still required for anything that signs</td></tr><tr><td><code>FURLPAY_USDC_PEG_FEED_URL</code></td><td>Pre-trade peg guardrail</td><td>USDC/USD feed for the depeg monitor; defaults to CoinGecko&#39;s simple price. Any https endpoint answering <code>{ &quot;usd-coin&quot;: { &quot;usd&quot;: &lt;number&gt; } }</code>. Refreshed at most once per 30s; a failed feed is surfaced as an explicit <code>PEG_FEED_UNAVAILABLE</code> warning on every order — never a synthetic price, and a depeg halt in force stays until real data proves recovery</td></tr></tbody></table><h2 id="exchange-credentials" tabindex="-1">Exchange credentials <a class="header-anchor" href="#exchange-credentials" aria-label="Permalink to &quot;Exchange credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Used by</th><th>Notes</th></tr></thead><tbody><tr><td><code>BINANCE_API_KEY</code></td><td>Binance spot</td><td>Create with spot trading enabled, <strong>withdrawals disabled</strong>, IP-bound</td></tr><tr><td><code>BINANCE_API_SECRET</code></td><td>Binance spot</td><td>HMAC-SHA256 signing, <code>recvWindow</code> enforced</td></tr><tr><td><code>FURLPAY_BINANCE_ENV</code></td><td>Binance</td><td><code>testnet</code> or <code>mainnet</code> — distinct constants, never silently swapped</td></tr></tbody></table><h2 id="rpc-endpoints-public-defaults-bring-your-own-provider" tabindex="-1">RPC endpoints (public defaults; bring your own provider) <a class="header-anchor" href="#rpc-endpoints-public-defaults-bring-your-own-provider" aria-label="Permalink to &quot;RPC endpoints (public defaults; bring your own provider)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Used by</th><th>Default</th></tr></thead><tbody><tr><td><code>STELLAR_HORIZON_URL</code></td><td>tx verify, Stellar tooling</td><td>network-dependent Horizon</td></tr><tr><td><code>SOLANA_RPC_URL</code></td><td><code>solana status/balance</code></td><td><code>https://api.mainnet-beta.solana.com</code></td></tr><tr><td><code>ETHEREUM_RPC_URL</code></td><td>JS app surface</td><td><code>https://cloudflare-eth.com</code></td></tr><tr><td><code>BASE_RPC_URL</code></td><td>JS app surface</td><td><code>https://mainnet.base.org</code></td></tr><tr><td><code>ARBITRUM_RPC_URL</code></td><td>JS app surface</td><td><code>https://arb1.arbitrum.io/rpc</code></td></tr></tbody></table><h2 id="oracle-jupiter" tabindex="-1">Oracle &amp; Jupiter <a class="header-anchor" href="#oracle-jupiter" aria-label="Permalink to &quot;Oracle &amp; Jupiter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>FURLPAY_PYTH_HERMES_URL</code></td><td>Optional authorized Pyth Hermes gateway base URL — the Pyth provider is inactive without it (public Hermes is auth-gated)</td></tr><tr><td><code>FURLPAY_PYTH_FEED_IDS</code></td><td>JSON map <code>{&quot;SOL&quot;:&quot;0x…&quot;}</code> of verified Pyth feed ids (required with the gateway); no feed ids ship baked in</td></tr><tr><td><code>FURLPAY_JUPITER_API_URL</code></td><td>Jupiter API base for <code>solana price/quote</code> (default: public Lite API)</td></tr></tbody></table><h2 id="platform-auth-finance" tabindex="-1">Platform, auth &amp; finance <a class="header-anchor" href="#platform-auth-finance" aria-label="Permalink to &quot;Platform, auth &amp; finance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Used by</th><th>Secret</th><th>Notes</th></tr></thead><tbody><tr><td><code>FURLPAY_ENV</code></td><td>JS app surface (pay TUI)</td><td>No</td><td>Exact string <code>live</code> opts into live-environment semantics; unset is never live</td></tr><tr><td><code>ANTHROPIC_API_KEY</code></td><td>AI support chat engine</td><td><strong>Yes</strong></td><td>Only the assistant chat; trading never needs it</td></tr><tr><td><code>FURLPAY_FINANCE_WEBHOOK_URL</code></td><td>finance events</td><td>No</td><td>Signed webhook receiver for ledger events (optional)</td></tr><tr><td><code>FURLPAY_FINANCE_APPROVER_TOKEN</code></td><td><code>finance approval approve</code></td><td><strong>Yes</strong></td><td>Shared-secret bearer token the human approver must present when set; server-side only, never argv</td></tr></tbody></table><h2 id="behavior-master-gates" tabindex="-1">Behavior &amp; master gates <a class="header-anchor" href="#behavior-master-gates" aria-label="Permalink to &quot;Behavior &amp; master gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td><code>FURLPAY_LIVE</code></td><td><strong>Live-execution master gate</strong> (<code>src/capabilities/registry.ts</code>): signing paths call <code>assertLiveAllowed()</code>; without <code>FURLPAY_LIVE=1</code> the surface stays inert with a clear refusal. On top of per-surface credentials</td><td>unset = inert</td></tr><tr><td><code>FURLPAY_NO_BROWSER</code></td><td>Device auth prints the URL instead of opening a browser</td><td>unset</td></tr><tr><td><code>FURLPAY_QUIET_TRUST_WARNING</code></td><td>Suppresses the repeated agent-trust warning banner</td><td>unset</td></tr><tr><td><code>NO_COLOR</code></td><td>Presence (any value, including <code>0</code> or empty) disables all color</td><td>unset</td></tr><tr><td><code>COLORTERM</code>, <code>TERM</code>, <code>WT_SESSION</code></td><td>Color-level detection (truecolor / 256 / 16)</td><td>—</td></tr><tr><td><code>NODE_ENV</code>, <code>FURLPAY_ENV</code></td><td>Environment hints; <code>production</code>/<code>live</code> gates sandbox fixtures</td><td>—</td></tr></tbody></table><h2 id="what-is-deliberately-absent" tabindex="-1">What is deliberately absent <a class="header-anchor" href="#what-is-deliberately-absent" aria-label="Permalink to &quot;What is deliberately absent&quot;">​</a></h2><ul><li>No <code>FURLPAY_PRIVATE_KEY</code>-style master override for Stellar: Stellar keys live in the encrypted keystore or hardware — never env, never argv.</li><li>No screening-vendor API keys: OFAC/travel-rule integrations are not implemented in this build and the CLI does not pretend otherwise.</li><li>No <code>NEXT_PUBLIC_</code> anything: this is a CLI; secrets never ship to a browser.</li></ul><h2 id="hygiene-rules-the-cli-enforces" tabindex="-1">Hygiene rules the CLI enforces <a class="header-anchor" href="#hygiene-rules-the-cli-enforces" aria-label="Permalink to &quot;Hygiene rules the CLI enforces&quot;">​</a></h2><ul><li><strong>Argv secrets are refused</strong> — mnemonics/keys on stdin only (<code>wallet import</code>, <code>login --key</code>).</li><li><strong>Terminal echo is suppressed</strong> for interactive seed-phrase/key input.</li><li>The session cookie attaches <strong>only</strong> to <code>furlpay.com</code> over TLS or loopback — pointing <code>--api-base</code> elsewhere sends the request credential-less and says so.</li><li>Cleartext <code>http://</code> is refused for remote targets, and refused even on loopback when the environment is <code>live</code>.</li><li>URLs with embedded credentials (<code>https://user:pass@host</code>) are refused outright.</li></ul>',27)])])}const b=t(o,[["render",i]]);export{u as __pageData,b as default};
